-- OS::JOB 0.4.0 - importer une seule fois APRES 003, sans supprimer les données.
USE os_job;
ALTER TABLE applications ADD UNIQUE KEY uq_application_offer_user (user_id,job_offer_id);
CREATE TABLE IF NOT EXISTS application_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, event_type VARCHAR(40) NOT NULL, details TEXT NULL, occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE, INDEX(application_id,occurred_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS application_contacts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, full_name VARCHAR(160) NOT NULL, job_title VARCHAR(160) NULL, email VARCHAR(190) NULL, phone VARCHAR(60) NULL, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS application_interviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, interview_mode ENUM('telephone','video','onsite','other') NOT NULL DEFAULT 'video', location VARCHAR(255) NULL, notes TEXT NULL, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE, INDEX(starts_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS application_reminders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, due_at DATETIME NOT NULL, title VARCHAR(200) NOT NULL, done TINYINT(1) NOT NULL DEFAULT 0, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE, INDEX(due_at,done)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS application_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, application_id BIGINT UNSIGNED NOT NULL, document_type ENUM('cv','letter','other') NOT NULL DEFAULT 'other', original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(100) NOT NULL, mime_type VARCHAR(100) NOT NULL, uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- Reprendre les offres déjà suivies : aucun changement de statut des offres.
INSERT INTO applications (user_id,job_offer_id,status,applied_at)
SELECT o.user_id,o.id,o.status,CASE WHEN o.status IN ('applied','interview','rejected','accepted') THEN o.updated_at ELSE NULL END
FROM job_offers o LEFT JOIN applications a ON a.user_id=o.user_id AND a.job_offer_id=o.id WHERE a.id IS NULL;
